def parse_date(text):
    """
    Read the free-text dates users typed: d/m/yyyy (also with - or .), yyyy-mm-dd,
    a bare year (taken as 1 January), and m/d/yyyy when the second number can only
    be a day. Returns (date or None, note) where note says how the value was read.
    """
    text = (text or '').strip()
    if not text:
        return None, None
    if re.fullmatch(r'\d{4}', text):
        return datetime.date(int(text), 1, 1), 'year only, set to 1 January'
    match = re.fullmatch(r'(\d{4})-(\d{1,2})-(\d{1,2})', text)
    if match:
        year, month, day = map(int, match.groups())
        note = None
    else:
        match = re.fullmatch(r'(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})', text)
        if not match:
            return None, 'not a date'
        day, month, year = map(int, match.groups())
        note = None
        if month > 12 and day <= 12:
            day, month = month, day
            note = 'read as month/day/year'
    try:
        return datetime.date(year, month, day), note
    except ValueError:
        return None, 'impossible date'


def normalize_dates(apps, schema_editor):
    """Rewrite each text date as yyyy-mm-dd (or NULL) so the column can be cast to date."""
    for model_name, field in DATE_COLUMNS:
        model = apps.get_model('lwf', model_name)
        for pk, text in model.objects.exclude(**{field: None}).values_list('pk', field):
            value, note = parse_date(text)
            if note:
                print('\n  %s.%s id=%s: %r %s -> %s' % (model_name, field, pk, text, note, value or 'NULL'), end='')
            model.objects.filter(pk=pk).update(**{field: value.isoformat() if value else None})
    # PostgreSQL refuses ALTER TABLE while deferred constraint checks from these
    # updates are pending in the same transaction; run them now.
    if schema_editor.connection.vendor == 'postgresql':
        schema_editor.execute('SET CONSTRAINTS ALL IMMEDIATE')


